#include "TrainingTarget.h"
#include "RangeGeometry.h"
#include "Components/StaticMeshComponent.h"
ATrainingTarget::ATrainingTarget(){PrimaryActorTick.bCanEverTick=false;RootComponent=CreateDefaultSubobject<USceneComponent>(TEXT("Rig"));Upper=CreateDefaultSubobject<USceneComponent>(TEXT("Upper"));Upper->SetupAttachment(RootComponent);
 Head=Part(Upper,TEXT("Head"),TEXT("head"),{0,0,168},{34,34,34},true);Part(Upper,TEXT("Chest"),TEXT("torso"),{0,0,113},{28,48,58});Part(Upper,TEXT("Pelvis"),TEXT("torso"),{0,0,73.5},{27,43,21});
 for(int i=0;i<2;i++){float Sign=i==0?-1:1;auto* Arm=CreateDefaultSubobject<USceneComponent>(*FString::Printf(TEXT("Arm%d"),i));Arm->SetupAttachment(Upper);Arm->SetRelativeLocation({0,Sign*34,136});Arms.Add(Arm);Part(Arm,*FString::Printf(TEXT("UpperArm%d"),i),TEXT("arm"),{0,0,-20},{18,17,40});Part(Arm,*FString::Printf(TEXT("Forearm%d"),i),TEXT("arm"),{-2.5f,0,-51},{16,15,22});
 auto* Hip=CreateDefaultSubobject<USceneComponent>(*FString::Printf(TEXT("Hip%d"),i));Hip->SetupAttachment(RootComponent);Hip->SetRelativeLocation({0,Sign*13,63});Hips.Add(Hip);auto* Knee=CreateDefaultSubobject<USceneComponent>(*FString::Printf(TEXT("Knee%d"),i));Knee->SetupAttachment(Hip);Knee->SetRelativeLocation({0,0,-29});Knees.Add(Knee);Part(Hip,*FString::Printf(TEXT("Thigh%d"),i),TEXT("leg"),{0,0,-14.5f},{20,18,29});Part(Knee,*FString::Printf(TEXT("Shin%d"),i),TEXT("leg"),{-1,0,-17},{18,16,34});}
}
UPrimitiveComponent* ATrainingTarget::Part(USceneComponent* Parent,const TCHAR* Name,FName Zone,const FVector& P,const FVector& Size,bool Sphere){auto* Mesh=CreateDefaultSubobject<UStaticMeshComponent>(Name);Mesh->SetupAttachment(Parent);Mesh->SetRelativeLocation(P);Mesh->SetRelativeScale3D(Size/100);Mesh->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,Sphere?TEXT("/Engine/BasicShapes/Sphere.Sphere"):TEXT("/Engine/BasicShapes/Cube.Cube")));Mesh->SetCollisionEnabled(ECollisionEnabled::QueryOnly);Mesh->SetCollisionResponseToAllChannels(ECR_Ignore);Mesh->SetCollisionResponseToChannel(ECC_Visibility,ECR_Block);Mesh->ComponentTags.Add(Zone);Parts.Add(Mesh);return Mesh;}
void ATrainingTarget::SpawnAt(const FVector& Position,double Time,int Seed){SetActorLocation(Position);Anchor=Previous=Position;SpawnTime=Time;Health=150;Generation++;ShotsReceived=0;Active=true;Lateral=0;Crouch=0;Random=valoprac::Random(Seed);Direction=Random.next()>.5?1:-1;NextChange=Time+Random.range(.65,1.5);ChangedAt=Behavior==TEXT("appearing")?Time:-100;ReactionRecorded=Behavior!=TEXT("appearing");SetActorHiddenInGame(false);SetActorEnableCollision(true);
 if(!HeadMaterial){HeadMaterial=ARangeGeometry::Material(this,FLinearColor(.95,.40,.33),.65);BodyMaterial=ARangeGeometry::Material(this,FLinearColor(.27,.40,.45),.65);for(UPrimitiveComponent* P:Parts)P->SetMaterial(0,P==Head?HeadMaterial:BodyMaterial);}
 Step(Time,0);
}
void ATrainingTarget::Step(double Time,double Dt){Previous=GetActorLocation();if(!Active){double Age=Time-DeadAt;SetActorRotation(FRotator(float(-FMath::Min(1.0,Age/.2)*55),0,0));SetActorHiddenInGame(Age>.25);return;}SetActorRotation(FRotator::ZeroRotator);
 double Desired=0;if(Behavior==TEXT("strafe"))Desired=Direction*2.1;if(Behavior==TEXT("random")||Behavior==TEXT("crouch"))Desired=Direction*2.3;if(Behavior==TEXT("stopGo"))Desired=std::sin((Time-SpawnTime)*2.3)>.15?Direction*2.4:0;if(Behavior==TEXT("peek"))Desired=Direction*1.8;
 if(Behavior!=TEXT("stationary")&&Behavior!=TEXT("appearing")&&(Time>=NextChange||FMath::Abs(GetActorLocation().Y-Anchor.Y)>240)){Direction*=-1;NextChange=Time+Random.range(.65,1.8);ChangedAt=Time;ReactionRecorded=false;}
 Lateral=valoprac::approach(Lateral,Desired*SpeedMultiplier,Dt*12);AddActorWorldOffset({0,float(Lateral*100*Dt),0});Crouch=valoprac::approach(Crouch,Behavior==TEXT("crouch")&&std::sin(Time*1.4)>.15?1:0,Dt*4);
 double Stride=std::sin(Time*9)*std::min(.32,std::abs(Lateral)*.13);Upper->SetRelativeLocation({0,0,float(-43*Crouch+std::abs(Stride)*2.5)});Upper->SetRelativeRotation(FRotator(0,0,float(FMath::RadiansToDegrees(Stride*.04))));
 for(int i=0;i<2;i++){double S=i==0?Stride:-Stride;FVector P=Hips[i]->GetRelativeLocation();P.Z=63-20*Crouch;Hips[i]->SetRelativeLocation(P);Hips[i]->SetRelativeRotation(FRotator(float(FMath::RadiansToDegrees(S-.7*Crouch)),0,0));Knees[i]->SetRelativeRotation(FRotator(float(FMath::RadiansToDegrees(std::max(0.0,-S)+1.25*Crouch)),0,0));Arms[i]->SetRelativeRotation(FRotator(float(FMath::RadiansToDegrees(-S*.6)),0,0));}
}
bool ATrainingTarget::Hit(FName Zone,double Damage,bool HeadOnly,bool AnyHit,double Time){if(!Active)return false;ShotsReceived++;Health-=Damage;if(Zone==TEXT("head")||(!HeadOnly&&(AnyHit||Health<=0))){Active=false;DeadAt=Time;SetActorEnableCollision(false);return true;}return false;}
FVector ATrainingTarget::HeadPosition()const{return Head->GetComponentLocation();}
